colors={'medical':('#082b32','#1fbbb1'),'commerce':('#3b160e','#ff924c'),'insight':('#0d1d3f','#487dfa'),'taskflow':('#291034','#aa66e2'),'cinema':('#360b14','#e72542'),'backend':('#17332a','#63b98e'),'frontend':('#201f40','#8b8ce8'),'database':('#0c2936','#59b7d2'),'toolkit':('#3a2411','#d7a15d'),'career':('#2a0d21','#dd448e'),'intern':('#122938','#5eabd7'),'education':('#2c2317','#c8a777'),'certjava':('#26322b','#7fa98c'),'certcloud':('#172c3e','#69a8ce')}
